def max_chain_length(pairs: list[Pair], k: int) -> int:
    """
    Finds the longest chain which can be used to create a chain where 
    elements have values less than `k` and their index does not exceed `k`.
    """
    if not pairs or k <= 0:
        raise ValueError("Invalid Input")

    # Create a dictionary to store the elements with their rank based on value
    rank_dict = {}
    for num in sorted(pairs, key=lambda x: x.value1)[::-1]:
        rank = sum(pair.value2 for pair in ranks)
        ranks.append(num)
        rank_dict[num] = rank

    # Find the longest chain of elements with values less than `k`
    max_chain_length = 0
    ranks = [k]
    for num in ranks:
        if rank_dict[num] < k:
            ranks.append(ranks[-1] + pair.value2 for pair in ranks)
            max_chain_length = num

    return len(ranks) - 1  # Exclude the index of `k` from the final set of ranks
