    for i in range(1, len(pairs)):
        if pairs[i].first >= pairs[i-1].first and pairs[i].first < pairs[i].second:
            current_length += 1
        else:
            if current_length > longest_chain_length:
                longest_chain_length = current_length
            current_length = 1

    if current_length > longest_chain_length:
