def make_prime_factors(num):
    factors = []
    divisor = 2
    while divisor * divisor <= num:
        if num % divisor:
            divisor += 1
        else:
            num //= divisor
            factors.append(divisor)
    if num > 1:
        factors.append(num)
    return factors
def prime_num(n):
    factors = make_prime_factors(n)
    while factors:
        prime_factors = len(factors)  # Counter of prime factors
        first_factor = factors.pop(0)  # Smallest prime factor
        factors.append(factors.pop(0) // first_factor)  # Multiplying by smallest prime factor
    return prime_factors == 1

