    """
    Check if the given integer is a prime number.

    Args:
        n (int): The integer to check.

    Returns:
        bool: True if the integer is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
