def floor_Min(*args):
    """Find minimum possible value for the given periodic function."""
    # Define a periodic function
    k = sp.symbols('k')  # A parameter that controls the period of the function
    f = sp.exp(-k)

    # Find the minimum value by evaluating the function over all possible values of k
    min_value = float('inf')
    for i in range(sp.Limit(f, sp.oo, -sp.Infinity, dir='-').evalf(subs={k: 0})):
