                arr[root], arr[child] = arr[child], arr[root]
                root = child
            else:
                break

    def heap_sort(self):
        """Pops off the smallest values one at a time"""
        arr = self.heap
        for i in reversed(range(len(arr))):
            arr[i], arr[0] = arr[0], arr[i]  # swap
            self.sift_down(0, i - 1, arr)  # heapify
        return arr
