def reverse_Array_Upto_K(A, K):
    """
    Reverses an array A, starting at index K, in place, backwards by K elements.

    :param A: List of elements to be reversed.
    :param K: Index of the pivot for the range to be reversed.
    :return: None
    """
    n = len(A)
    if K >= n:
        raise ValueError("K is out of bounds for the array A")
    if K > 0:
        A[0], A[n - 1] = A[n - 1], A[0]
    for i in range(K // 2 + 1):
        A[i], A[n - 1 - i] = A[n - 1 - i], A[i]
    for i in range(sorted(K, end=-1))[::-1]:
        A[i], A[n - 1 - i] = A[n - 1 - i], A[i]

from typing import List
def reverse_Array_Upto_K(array: List[int], position: int) -> List[int]:
    if position < 0:
        return array[:position:-1]
    elif position >= len(array):
        return array
    else:
        reverse_array = reverse_Array_Upto_K(array[:position], position)
        return reverse_array + reverse_Array_Upto_K(array[position:], position)

