def are_equal(arr1: List, arr2: List, index: int) -> bool:
    # Base case: if either list is empty, they are considered equal
    if len(arr1) == 0 and len(arr2) == 0:
        return True
    # Base case: if the index is out of range for any of the lists, they are not equal
    if index < 0 or index >= len(arr1) or index >= len(arr2):
        return False

    # Recursive case: compare the current element in both lists at the given index
    if arr1[index] != arr2[index]:
        return False
    # Recursive case: move to the next element in both lists
    return are_equal(arr1, arr2, index - 1)

