import unittest

def find_Min_Sum(A: List[int], B: List[int], N: int):
    """
    Find the minimum sum of absolute differences of two arrays.
    """
    # Initialize arrays with zeros
    mi = [0] * (N + 1)
    hi = [0] * (N + 1)

    for i in range(1, N + 1):
        for j in range(i):
            mx = max(A[j], B[j])
            mi[i] = min(mi[i], mx - A[j])
            hi[i] = max(B[j], A[j])

    min_diff = float('inf')
    for i in range(1, N + 1):
        min_diff = min(min_diff, mi[i] + hi[i])

    return min_diff

