def max_sum_of_three_consecutive(numbers, target):
    """
    Find the maximum sum that can be formed which has no three consecutive elements present,
    starting from the end of the array.

    :param numbers: A list of integers representing the sequence.
    :param target: The target sum for the maximum sum.
    :return: The maximum sum that can be formed with no three consecutive elements.
    """

    max_sum = 0
    for start_index in range(len(numbers) - 3):
        # Check if there are no more than three consecutive numbers left
        if start_index >= 3:
            for index in range(start_index + 4, len(numbers)):
                if numbers[index] != numbers[start_index + 1] and numbers[index] != numbers[start_index + 2] and numbers[index] != numbers[start_index + 3]:
                    # Check if the current sum is less than or equal to the target
                    if index >= start_index + 4 and numbers[index] + numbers[start_index + 1] + numbers[start_index + 2] <= target:
                        break  # Stop searching if the condition is met
                else:
                    break  # No need to check further for this range
        else:
            # Check if the current sum is less than or equal to the target
            if numbers[start_index] + numbers[start_index + 1] + numbers[start_index + 2] <= target:
                break  # Stop searching if the condition is met
        max_sum = max(max_sum, numbers[start_index] + numbers[start_index + 1] + numbers[start_index + 2])  # Note: Skip the current number

    return max_sum
