from typing import List

def replace_chars(arr: List[str], char: str, n: int) -> List[str]:
    for i in range(len(arr)):
        arr[i] = arr[i][:n] if arr[i][-1] == char or arr[i][-1] == '\\.' else arr[i].replace(char, '\\.' + char +
                                                                           '\\.' * n)
        arr[i] = arr[i][:n] if arr[i][-1] == '\\' and arr[i][-2] == ',' else arr[i]
    return arr

