import math

def smallest_divisor(n: int) -> int:
    """
    Find the smallest prime divisor of a number.

    Args:
        n (int): The input number.

    Returns:
        int: The smallest prime divisor.
    """
    divs = set()  # Set to store the prime factors
    i = 2  # Start from 2 since any number is divisible by 1

    while i * i <= n:
        while n % i == 0:
            divs.add(i)  # Add prime factor to list if it divides n exactly
            n //= i  # Divide n by the prime factor
        i += 1

    if n > 1:
        divs.add(n)  # Add all remaining factors to the list

    # Get the smallest value from the set
    smallest_divisor = min(divs)

    return smallest_divisor

# Test function to check the correctness of the smallest_divisor function
def test():
    assert smallest_divisor(10) == 2
    assert smallest_divisor(25) == 5
    assert smallest_divisor(28) == 2
    assert smallest_divisor(99) == 3
    print("All tests passed!")

