def freq_element(numbers):
    """
    Find the frequency of each element in the given list.

    :param numbers: A list of integers
    :return: A dictionary where each key is an unique number (integer) from the list, 
             and its value is the number of times it appears in the list.
    Examples:
    >>> freq_element([4, 5, 4, 5, 6, 6, 5, 5, 4])
    {4: 3, 5: 4, 6: 2}
    >>> freq_element([])
    {}   
    >>> freq_element([8, 2, 3, 5, 4, 5, 4, 8, 5, 6, 6])
    {8: 1, 2: 1, 3: 1, 5: 3, 4: 2, 6: 2}
    """
    frequency_count = defaultdict(int)
    for number in numbers:
        frequency_count[number] += 1
    return dict(frequency_count)

