def group_element(pair_list: List[tuple]) -> dict:
    """
    Takes a list of tuples where each tuple contains two elements.
    Each tuple represents a quadruple where the first element is unique and denotes the group size.
    The function groups the elements for each unique group size in the order given by the values of their first elements.

    Example:
    >>> group_element([(6, 5), (2, 7), (2, 5), (8, 7), (9, 8), (3, 7)])
    {5: [6, 2], 7: [2, 8, 3], 8: [9]}

