def alternate_elements(elements):
    """
    Return a list of elements from another given list, the list elements are alternating in reverse order.
    @param elements: List to return alternate elements from.
    @returns a list of elements from another given list, the list elements are alternating in reverse order.
    """
    # Create an empty list to store the reversed alternating elements
    result = []

    # Loop through each element in the given list
    for index, item in enumerate(elements[::-1]):
        # Append the current element to the result list, followed by its future counterpart to the right.
        result.append(item)
        if index < len(elements) - 1:
            # If it's not the last element, append its future counterpart to the left.
            result.append(elements[index + 1])

    return result

