def max_average_of_path(matrix: List[List[int]], n: int) -> float:
    """
    Finds the maximum average of paths with length 3 or more.

    :param matrix: A square matrix of size n*n
    :param n: The size of the square matrix
    :return: The maximum average of paths with length 3 or more
    """
    def maxsum(arr):
        """Max sum using dynamic programming"""
        dp = [0] * n
        dp[0] = arr[0]
        for i in range(1, n):
            dp[i] = max(dp[i - 1], 0) + arr[i]
        return max(dp)

    def extrapare(x: int):
        """
        Assembles a path from its coordinates
        """
        total = sum(matrix[c] for c in zip(*x))
        return tuple([c for c in zip(*x) if sum(m >= total) > 0])

    # Solves main problem
    paths = set()  # Set is used to avoid duplicates
    for ri in range(2 ** n):
        for fac in range(n):
            ip = [ri >> fac & 1]
            if ip[0] == 0:
                continue  # Error, should not happen
            p = extrapare(ip)
            if maxsum(p) / n > sum([[matrix[m][c] for c in zip(*p)] for m in range(n)]) / n:
                paths.add(maxsum(p) / n)

    # Calculate the maximum average
    return max(map(sum, zip(*paths))) / n

