from collections import defaultdict

def count_same_pair(nums1: List[int], nums2: List[int]) -> int:
    """Returns the number of pairs i,j where nums1[i] = nums2[j]"""
    same_pair = defaultdict(int)
    for i in range(len(nums1)):
        same_pair[nums1[i]] += 1
        same_pair[nums2[i]] -= 1
    count = 0
    for _, count in same_pair.items():
        if count > 0:
            count += 1
    return count

