# Write a python function to toggle bits of the number except the first and the last bit.
def toggle_middle_bits(num):
    # Get the binary representation of the given number
    binary_representation = bin(num)[2:]

    # Remove the first and last bit and concatenate them
    toggled = binary_representation[:len(binary_representation)//2] + binary_representation[len(binary_representation)//2:]

    # Convert the shifted binary string back to decimal
    toggle = int(toggled, 2)

    return toggle
