class Solution:
    def countUniqueSublists(self, nums: List[List[int]]) -> int:
        n = len(nums)
        indexMap = Counter()
        sublists = [[] for _ in range(n)]
        for i, num1 in enumerate(nums):
            for j, num2 in enumerate(nums[i + 1:]):
                sublists[i] = [*sublists[i], num1]
                sublists[i + 1] = [*sublists[i + 1], num1]
                sublists[i + 1] = [*sublists[i + 1]]
            sublists.append([num2])

        uniqueCountedSublists = set()  # Store the sets of ordered unique lists

        # Populate uniqueCountedSublists with unique sublists for each length k
        for k in range(len(n)):
            for j in range(k + 1):
                if j == 0:
                    if [nums[i * j]] not in uniqueCountedSublists:
                        uniqueCountedSublists.add([nums[i * j]])
                else:
                    uniqueS = []
                    for s1 in uniqueCountedSublists:
                        s2 = [sublists[i][j - 1]] + s1
                        if s2 not in sublists:
                            uniqueS.append(s2)
                    uniqueCountedSublists.update(uniqueS)

        return len(uniqueCountedSublists)

