    numbers_copy = numbers.copy()
    for i in range(n):
        min_diff = None
        for j in range(i + 1, n):
            if j not in A:
                # Find the minimum number between the smallest and the next smallest in the array
                num1 = min(numbers_copy[j], numbers_copy[i])
                num2 = max(numbers_copy[j], numbers_copy[i])
                # Update the minimum difference
                if min_diff is None or (num2 - num1) < min_diff:
                    min_diff = num2 - num1
        # Set the current number index to A
        A.remove(i)
    # Return the minimum difference if exists
    if min_diff is not None:
        return min_diff
    else:
        return None

