def sum_non_repeated(array, n):
    """
    Find the sum of non-repeated elements in a given array.

    Args:
    array : list, the input array.
    n : int, upper limit of the sum.

    Returns:
    int, sum of non-repeated elements.

    """
    non_repeated_elements = set([])
    for element in array:
        if element in non_repeated_elements:
            non_repeated_elements.remove(element)
        else:
            non_repeated_elements.add(element)
    return sum(non_repeated_elements)

def find_Sum(array, n):
    """
    Given an array and the sum n, returns the sum of all elements that have a unique value.
    >>> find_Sum([1,2,3,1,1,4,5,6],8)
    21
    """
    # Dictionary to keep track of seen elements and corresponding indices
    seen = {}

    # Iterate through the array to mark seen elements and indices
    for i in range(n):
        # If the current element is not yet seen, mark it and return the sum
        if array[i] not in seen:
            seen[array[i]] = i
            return sum(array[:i]) + sum(array[i + 1 :])

    # If all elements are repeated, return 0
    return 0

