from collections import defaultdict

def Odd_Length_Sum(t: List[int]) -> int:
    """
    Calculate the sum of all odd length subarrays.

    Parameters:
    t (List[int]): The input list of integers.

    Returns:
    int: The sum of all odd length subarrays of the input list.

    Example:
    >>> Odd_Length_Sum([1, 2, 4])
    14
    >>> Odd_Length_Sum([-1, -1, -1])
    -2
    """
    # Calculate the prefix sum of t
    ps = [t[0]]
    for i in range(1, len(t)):
        ps.append(t[i] + ps[-1])

    # Generate substrings of odd length and count their odd lengths
    odds = defaultdict(int)
    for i in range(len(t) - 1):
        for j in range(i + 1, len(t) + 1, 2):
            substring = t[i:j]
            size = len(substring)
            odds[size] += ps[j] - ps[i]

    # Get the sum of subarrays whose lengths are even
    return sum(odds.values())

