    >>> mul_even_odd([1, 3, 5, 7, 4, 1, 6, 8])
    4
    >>> mul_even_odd([10, 20, 30, 10, 5])
    0
    """
    even = []
    odd = []
    for num in num_list:
        if num % 2 == 0:
            even.append(num)
        else:
            odd.append(num)
    if len(even) > 0:
        product_of_even = 1
        for num in even:
            product_of_even *= num
    else:
        product_of_even = 0
    if len(odd) > 0:
        product_of_odd = 1
        for num in odd:
            product_of_odd *= num
    else:
        product_of_odd = 0
    return product_of_even * product_of_odd

