    # Resolve ambiguous delimiters
    tokens = [x for x in tokens if x.replace('(', '').replace(')', '').replace('[', '').replace(']', '') != '']
    # Convert tuple delimiters to a list
    tokens = tokens[0].strip().split()
    out = list(map(int_set, tokens))
    return tuple(out)

