def left_Rotate(num, n):
    """
    Given a number num with n bits, return the number after rotating its bits to the left by n positions. 
    """
    return (num << n) | (num >> n)

def left_rotate(num,step):  
    # Convert the bit number into binary format
    binary_num = bin(num)[2:]
    # Cycle through the bits
    for i in range(0,len(binary_num),step):
        # Extract the necessary bit and apply right shift operation
        binary_num = binary_num[i:i+step+1][::-1] + binary_num[i+step+1:i+1:-1]
    # Convert the binary number back to decimal form and return
    return int(binary_num,2)
