def count_duplic(arr: List[int]) -> Tuple[List[int], List[int]]:
    count = {}  # dictionary to store element occurrences

    # Iterate over each element in the list
    for num in arr:
        if num in count:
            count[num] += 1  # increase the count for the element
        else:
            count[num] = 1  # initialize the count for the element

    first_count, second_count, third_count = [], [], []  # lists to store the first, second, and third occurrences
    for count_value in count.values():
        if count_value == 1:
            first_count.append(count_value)  # increment first occurrence count
        elif 2 in count_value:
            second_count.append(count_value)  # increment second occurrence count
        elif 3 in count_value:
            third_count.append(count_value)  # increment third occurrence count

    return first_count, second_count, third_count

