def find_second_most_common_string(strings: List[str]) -> str:
    """
    Finds the second most common string in a sequence of strings.

    Args:
        strings (List[str]): A list of strings to be analyzed.

    Returns:
        str: The second most common string in the list, or None if there is no such string.

    Raises:
        AssertionError: If the input is not a list of strings.
    """
    assert isinstance(strings, list), "Input must be a list of strings."
    counts = {}
    for string in strings:
        if string in counts:
            counts[string] += 1
        else:
            counts[string] = 1

    # Find the count of each count categories
    count_dicts = {}
    count = None
    candidates = set(strings)
    for string in count_dicts.keys():
        count = 0
        for string2 in candidates:
            if counts[string2] == counts[string]:
                count += 1
        count_dicts[string], candidate = candidates.pop(count), string
    if candidate is not None:
        return candidate

    # Find the second most frequent one
    second_most = None
    second_most_count = 0
    second_most_arg = None
    for string in count_dicts:
        if count_dicts[string] == second_most_count:
            second_most = string
            if second_most_arg is not None:
                return None  # Both most % and second most % are equal
        elif count_dicts[string] > second_most_count:
            second_most_arg = count_dicts[string]
            second_most_count = count_dicts[string]  

    if second_most_arg:
        return second_most

