            for k in j[1:]:
                if v > k[1]:
                    j[1] = v
                    v = k
            s = s.ljust(chars, ' ')
        moved = False
        for j in hashed_list[:tall_points]:
            chars = len(j[0])
            for k in j[1:]:
                if v > k[1]:
                    j[1] = v
                    v = k
            s = s[:chars] + str(v) + s[chars:]
            moved = True
        if not moved:
            tall_points += 1
        hashed_list[tall_points + 1:j] = (s, v)
        tall_points += 1
    return hashed_list

