        next_num = 1
        while len(pq) < n:
            pq_item, price = heapq.heappop(pq)
            next_num = max(next_num, next(pq_item[1]))
            for root, size in pq:
                if price * size <= next_num:
                    heapq.heappush(pq, (price * size, price * size))
