def sum_of_odd_factors(n):
    """
    Given a positive integer n, this function returns the sum of odd factors of n.
    """
    # Create an empty set to store the odd factors
    odd_factors = set()

    # Divide the number by 2 until it's even
    while n % 2 == 0:
        odd_factors.add(2)
        n //= 2

    # For odd numbers
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            odd_factors.add(i)
            n //= i

    # If n remains 1, it must be the only odd factor
    if n > 1:
        odd_factors.add(n)

    # Sum up all the odd factors and return the result
    return sum(odd_factors)

