    count = 0
    for i in range(size):
        if nums[i] > nums[i+1]:
            j = i
            while j < size and nums[j] < nums[j-1]:
                temp = nums[j]
                nums[j] = nums[j-1]
                nums[j-1] = temp
                j += 1
            count += 1 * (size - (j-1))
