def is_isomorphic(s1: str, s2: str) -> bool:
    """
    验看两个字符串是否为m之所以m的对等字符串。

    参数：
    - s1: 字符串1
    - s2: 字符串2

    返回值：
    - True, 如果它们是一种对等的字符串
    - False, 如果它们不具备m之外的道理
    """
    # 判断两字符串的长度是否相等
    if len(s1) != len(s2):
        return False

    # 创建用于映射s1和s2的映射集合，以及类似映射集合
    map1 = set()
    map2 = set()

    # 遍历s1和s2字符串，并检查它们是否为对等的，只要他们第一个字符不同，并且对应映射的值不同，那么就判断为不对等的
    for i in range(len(s1)):
        if s1[i] in map1:
            if map1[s1[i]] != s2[i]:
                return False
        else:
            if s2[i] in map2:
                return False
            map1.add(s1[i])
            map2.add(s2[i])

    # 如果这些条件都不符合，则返回True
    return True
