def is_isomorphic(s1, s2):
    # Check if the lengths of two strings are different
    if len(s1) != len(s2):
        return False
    # Create a dictionary to store the character mappings
    mapping = {}
    visited = set()
    for i in range(len(s1)):
        if s1[i] not in mapping:
            # Duplicate letters are not allowed
            if s2[i] in visited:
                return False
            # Update the character mappings
            mapping[s1[i]] = s2[i]
            visited.add(s2[i])
        elif mapping[s1[i]] != s2[i]:
            return False
    return True

