def find_extra(arr: list, diff: int, val: int) -> int:
    """
    Find the index of an extra element present in one sorted array.

    Args:
        arr (list): The sorted array.
        diff (int): The difference between the given value and the element in the array.
        val (int): The value to compare with the element in the array.

    Returns:
        int: The index of the extra element.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == val:
            if mid > 0 and arr[mid - 1] == diff:
                right = mid - 1
            elif mid < len(arr) - 1 and arr[mid + 1] == diff:
                left = mid + 1
            else:
                return mid
        elif arr[mid] > val:
            right = mid - 1
        else:
            left = mid + 1
    return -1

