def max_sum_subseq(s):
    """Given a list of integers, find the maximum sum of subsequences of given array with no adjacent elements.

    The function assumes that the list s has at least one element, and each element is non-negative. Also, the sum of
    elements in the array is at least 3 (which is given by the "assert" statement in the question.

    Args:
        s (list): The list of integers.

    Returns:
        int: The maximum sum of subsequences without adjacent elements.
    """
    memo = [None] * len(s)
    # Initialize memoization table
    if s[0] >= 0:
        memo[0] = s[0]
    if s[0] > 0:
        for i in range(1, len(s)):
            if s[i] + memo[i - 1] - s[i - 1] < 0:
                memo[i] = s[i] 
            else:
                memo[i] = s[i] + memo[i - 1] - s[i - 1]
    else:
        for i in range(1, len(s)):
            memo[i] = -s[i] + memo[i - 1]
    return max(memo)

