def sort_list_last(tuples: list) -> list:
    """
    Sort the given list of non-empty tuples in increasing order by the last element in each tuple.

    Args:
        tuples (list): A list of tuples.

    Returns:
        list: A new list of sorted tuples.
    """
    def last_element(el):
        """Return the last element of a tuple"""
        return el[-1]

    def last_tuple_tuple(last_el, list_):
        """Return the last value of the tuple that lists in list_"""
        return list_.removeif(lambda tu: tu[0] == last_el)()[0][-1]

    def reverse(tuples):
        """Reverse a list of tuples in place"""
        tuples.reverse()
        return tuples

    def sort_by_last(tuple_):
        """Sort a tuple by the last element and apply min to each tuple in arg"""
        return min(tuple_)

    return sorted(tuples, key = sort_by_last)

