def check(array, n):
    if len(array) <= 2:
        return True

    # find indices to swap
    i1 = 0
    for i in range(1, n):
        if array[i] != array[i - 1]:
            i1 = i
            break

    i2 = i1 - 1
    i3 = n - 1 - i1

    if array[i1] > array[i2] or array[i2] > array[i3]:
        return False

    return check(array[0:i1], i1) and check(array[i1+1:i3+1], i3- (i2+1) ) and check(array[i2+1:], n - (i1 + i3-1))

