    """
    A Python function that counts the total unset bits (falsy bits such as zero, negative, and 1) from 1 to n.

    Args:
        n (int): The end value of iteration.

    Returns:
        int: The count of unset bits from 1 to n.

    Examples:
        - count_Unset_Bits(2) <--- 1
        - count_Unset_Bits(3) <--- 2
        - count_Unset_Bits(5) = 2 => 0 + 1

    Complexity:
        O(1) for counting and basic implementation.
        O(1) for counting basic implementation.
        O(n) for "skipping" the arguments to other tests.
    """
    bits = bin(n)[2:]  # Strip starting 'b'
    unset_bits = len(bits) - bits.count('1')
    return unset_bits

