            return helper(n-1, k)+helper(n-1, k+1)

    A = {}
    for i in range(0, n+1):
        A[i] = []
        for j in range(0, i+1):
            A[i].append(helper(n, i)+helper(n-1, j+1))

    return sum(A[n])

