def previous_palindrome(n: int) -> int:
    # Base case: for palindromes greater than 111, find the previous palindrome from 10 to 1
    if n > 111:
        stored_value = 10
    #: Check if the number is odd
    elif n & 1 == 1:
        stored_value = int(n / 10 + stored_value)
    else:
        stored_value = n
    # Find the previous palindrome
    used_numbers = {}
    i = 2  # Roots from 3 onwards are too large
    while i * i <= stored_value:
        if stored_value % i == 0:
            prev = stored_value // i
            if prev not in used_numbers:
                used_numbers[prev] = i
            used_numbers[i] = prev
        i += 1
    # Adjusted pattern to find previous palindrome (even numbers)
    d = used_numbers[int(n ** .5)]
    prev, not_found = next((b, used_numbers[b]) for b in used_numbers if b % 2 == 0 and b is not d)
    return (prev + d ** 2) // 2

