    nums.sort()
    for i in range(len(nums) - 2):
        left, right = i + 1, len(nums) - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target_sum:
                return (i, left, right)
            elif current_sum < target_sum:
                left += 1
            else:
