def chunk_tuples(tuply, n):
    """
    Perform chunking of tuples each of size n.
    Args:
        tuply (iterable): Iterable of tuples to be chunked.
        n (int): Size of each chunk.

    Returns:
        list of tuples: A list of chunks, where each chunk is of size n.

    Tests:
        assert chunk_tuples(((10, 4, 5, 6, 7, 6, 8, 3, 4), 3)) == [(10, 4, 5), (6, 7, 6), (8, 3, 4)]
    """
    chunks = []
    for elem in tuply:
        if len(elem) == n:
            if len(chunks) == 0:
                chunks.append(list(elem))
            else:
                tmp = list(chunks[-1])
                if len(tmp) < n:
                    tmp.append(elem)
                    chunks[-1] = tmp
                else:
                    chunks.append(list(elem))
        else:
            chunks.append(elem)
    return chunks

