from typing import List

def find_max_product(arr: List[int]) -> tuple[int, int]:
    numbers = sorted(arr)
    n = len(numbers)

    if n <= 2:
        return (0, 1)  # Edge case for single or two duplicates

    # Find maximum product:
    max_product = numbers[n-1] * numbers[n-2] * numbers[n-3]

    # If there are more than 3 numbers, the product is largest:
    if max_product <= numbers[n-1] * numbers[n-2] * numbers[n-3]:
        return (numbers[n-1], numbers[n-3])

    # Binary search for the largest product:
    left, right = 0, n-1
    while left < right:
        middle = (left + right) // 2
        middle_product = numbers[middle] * numbers[middle+1] * numbers[middle+2]

        if middle_product > max_product:
            left = middle + 1
        else:
            right = middle
    return min(numbers[left], numbers[left+1]), numbers[left]
