    left, right = 0, n-1
    while left < right:
        middle = (left + right) // 2
        middle_product = numbers[middle] * numbers[middle+1] * numbers[middle+2]

        if middle_product > max_product:
            left = middle + 1
        else:
            right = middle
    return min(numbers[left], numbers[left+1]), numbers[left]

