    l, r = query(arr1, mn), query(arr2, mn)
    while l>=1 and r>=1:
        c = query(arr3, mn)
        if abs(c - l) < min(abs(c - r) for c in arr1) or ((c >= min(l, n_queries)) and (c >= r)):
            return [arr1[l-1], arr2[r-1], arr3[c-1]]
