def most_common_elem(text, num):
    count = {}
    for char in text:
        if char.isalpha():
            count[char] = count.get(char, 0) + 1
    sorted_unique = sorted(count.items(), key=lambda x: x[1], reverse=True)
    sorted_count = [x[1] for x in sorted_unique]
    results = [x for x in enumerate(sorted_count, start=1)]
    return [x[0] for x in results[:num]]

