import math

def nCr_mod_p(n, r, p):
    # Helper function to calculate factorial for n
    factorial_n = math.factorial(n)
    # Use the property of numbers to reduce the size of the computation
    if n < r:
        return 0
    if n < p:
        return 0
    while n > r:
        n = n // p
        r = r // p
    return factorial_n // (factorial_n // r // p)

