from typing import List

def min_sum_path(triangle: List[List[int]]) -> int:
    """
    Finds the minimum total path sum in the given triangle.
    """
    def findMinPath(row_start: int, col_start: int, row_len: int, col_len: int) -> int:
        if row_start >= row_len:
            return 0
        if col_start >= col_len:
            return findMinPath(row_start + 1, col_start, row_len, col_len)
        path_sum = triangle[row_start][col_start] + \
                   findMinPath(row_start + 1, col_start, row_len, col_len) + \
                   findMinPath(row_start + 1, col_start + 1, row_len, col_len)
        return min(path_sum, findMinPath(row_start + 1, col_start, row_len, col_len))

    return findMinPath(0, 0, len(triangle), len(triangle[0]))

